      id: 'kimi', name: 'moonshot kimi',
      models: ['kimi-latest', 'kimi-plus'],
      endpoint: 'https://api.moonshot.cn/v1/chat/completions',
      authHeader: 'Authorization',
      cost: { input: 0.006, output: 0.018 },
      latency: 1100, maxTokens: 128000,
      strengths: ['ultra_long_context', 'chinese_content', 'document_analysis'],
      fallback: 'claude_code', status: 'online'
    }
  },
  routingRules: {
    code_generation: ['claude_code', 'qwen', 'openrouter'],
    creative_writing: ['claude_code', 'kimi', 'openrouter'],
    data_analysis: ['qwen', 'claude_code', 'openrouter'],
    multilingual_zh: ['qwen', 'kimi', 'openrouter'],
    long_context_100k: ['kimi', 'openrouter', 'qwen'],
    cost_optimized: ['qwen', 'openrouter', 'kimi'],
    low_latency: ['qwen', 'kimi', 'claude_code'],
    fallback_safe: ['openrouter', 'qwen', 'kimi', 'claude_code']
